// Authentic Human Voice Audio Clips recorded by user for GramSetu
// For presentations, live demos, and authentic civic grievance redressal playback

export const HUMAN_VOICE_BASE64: Record<string, string> = {
  handpump_water: 'data:audio/ogg;base64,',
  road_pothole: 'data:audio/ogg;base64,',
  transformer_sparks: 'data:audio/ogg;base64,',
  substation_outage: 'data:audio/ogg;base64,',
  sanitation_drainage: 'data:audio/ogg;base64,',
  pani_mein_ishu: 'data:audio/ogg;base64,',
  street_light: 'data:audio/ogg;base64,',
  general_civic: 'data:audio/ogg;base64,',
};

/**
 * Returns a high-fidelity human voice recording matching the issue content or category
 */
export function getRealisticHumanVoice(category?: string, text?: string): string {
  const lower = ((text || '') + ' ' + (category || '')).toLowerCase();
  
  if (lower.includes('water') || lower.includes('पानी') || lower.includes('handpump') || lower.includes('हैंडपंप') || lower.includes('नल') || lower.includes('जल')) {
    return HUMAN_VOICE_BASE64.handpump_water;
  }

  if (lower.includes('road') || lower.includes('pothole') || lower.includes('सड़क') || lower.includes('गड्ढा') || lower.includes('रास्ते') || lower.includes('स्कूटर')) {
    return HUMAN_VOICE_BASE64.road_pothole;
  }

  if (lower.includes('transformer') || lower.includes('spark') || lower.includes('चिंगारी') || lower.includes('तेल') || lower.includes('हादसा')) {
    return HUMAN_VOICE_BASE64.transformer_sparks;
  }

  if (lower.includes('substation') || lower.includes('सबस्टेशन') || lower.includes('बिजली') || lower.includes('power') || lower.includes('electric') || lower.includes('अंधेरा') || lower.includes('light')) {
    return HUMAN_VOICE_BASE64.substation_outage;
  }

  if (lower.includes('drain') || lower.includes('sanitation') || lower.includes('naali') || lower.includes('नाली') || lower.includes('कचरा') || lower.includes('गंदा') || lower.includes('बीमारी')) {
    return HUMAN_VOICE_BASE64.sanitation_drainage;
  }

  return HUMAN_VOICE_BASE64.general_civic;
}
